#!/usr/bin/env bash
# scripts/ros/test_cartesian_plan.sh — headless mock-stack smoke test of plan_crack_path (MOT-06.7).
#
# Plans the committed, test-only fixture paths3d (ros2_ws/src/crackvision_motion/test/fixtures/
# cartesian/smoke/, generated by make_fixture.py there) against its consistent fixture scene on the
# mock stack (no robot, no action client: plan_crack_path never commands motion), then checks the
# written plan file with an independent python3 block that makes its OWN /compute_fk and
# /check_state_validity calls rather than trusting the planner's recheck numbers:
#   - the two reachable segments (straight main, arc branch) are `full`; every trace configuration
#     puts tool_tip within 1 mm of the surface polyline offset 0.01 m along n with +X within 1 deg
#     of -n, and every fixture trace waypoint is hit by one of them; approach/retract endpoints sit
#     at 0.04 m; every configuration is valid and inside the inclusive limits; legs are continuous;
#   - the unreachable segment is `failed` with reasons and counts in the coverage denominator;
#   - the sunk segment is `surface_scene_mismatch` and never planned;
#   - coverage.fraction_by_length equals the fixture's expected value and complete is false;
# and finally re-runs with --require-full-coverage, which must exit 3 without writing a plan.
#
# Build is assumed done (scripts/ros/build_ws.sh). The planning config is the unmodified
# production config/motion/cartesian_planning.yaml. The mock stack is torn down on every exit path
# (_mock_stack.sh's EXIT/INT/TERM trap). Exit 0 only if every assertion holds.
set -uo pipefail
set -m

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"

set --
# shellcheck disable=SC1091
source "$SCRIPT_DIR/env_ros.sh" || exit 1
OVERLAY_SETUP="$REPO_ROOT/ros2_ws/install/setup.bash"
if [ ! -f "$OVERLAY_SETUP" ]; then
    echo "test_cartesian_plan.sh: $OVERLAY_SETUP not found — run scripts/ros/build_ws.sh first" >&2
    exit 3
fi
set +u
# shellcheck disable=SC1091
source "$OVERLAY_SETUP"
set -u
# shellcheck disable=SC1091
source "$SCRIPT_DIR/_mock_stack.sh"

FIX_REL="ros2_ws/src/crackvision_motion/test/fixtures/cartesian/smoke"
FIX="$REPO_ROOT/$FIX_REL"
LOG_DIR="$REPO_ROOT/logs"
mkdir -p "$LOG_DIR"
PLAN="$LOG_DIR/test_cartesian_plan.json"
PLAN_RFC="$LOG_DIR/test_cartesian_plan_require_full.json"
PLANNING_CFG="$REPO_ROOT/config/motion/cartesian_planning.yaml"
LAUNCH_LOG="$LOG_DIR/test_cartesian_plan_launch.log"
REGEN_DIR="$(mktemp -d)"
rm -f "$PLAN" "$PLAN_RFC"

fail() {
    echo "test_cartesian_plan.sh: FAIL: $*" >&2
    rm -rf "$REGEN_DIR"
    exit 1
}

# 0. The committed fixtures are exactly the generator's deterministic output.
python3 "$FIX/make_fixture.py" --out-dir "$REGEN_DIR" || fail "fixture generator failed"
for f in paths3d.json scene.yaml capture_stub.json expected.json; do
    cmp -s "$FIX/$f" "$REGEN_DIR/$f" || fail "committed $FIX_REL/$f differs from make_fixture.py output"
done
rm -rf "$REGEN_DIR"

# 1. Mock stack up, and its MoveIt services reachable before the planner's own short wait.
start_mock_stack "$LAUNCH_LOG" || exit 1
python3 - <<'PYEOF' || fail "MoveIt services did not come up; see $LAUNCH_LOG"
import sys, rclpy
from moveit_msgs.srv import (GetCartesianPath, GetMotionPlan, GetPlanningScene, GetPositionFK,
                             GetPositionIK, GetStateValidity)
rclpy.init()
node = rclpy.create_node("test_cartesian_plan_wait")
ok = all(node.create_client(t, n).wait_for_service(timeout_sec=120.0) for t, n in (
    (GetPositionFK, "/compute_fk"), (GetPositionIK, "/compute_ik"),
    (GetCartesianPath, "/compute_cartesian_path"), (GetMotionPlan, "/plan_kinematic_path"),
    (GetStateValidity, "/check_state_validity"), (GetPlanningScene, "/get_planning_scene")))
node.destroy_node()
rclpy.shutdown()
sys.exit(0 if ok else 1)
PYEOF

PLAN_ARGS=(--paths3d "$FIX/paths3d.json" --scene-config "$FIX/scene.yaml" --planning-config "$PLANNING_CFG")

# 2. Plan (partial coverage is expected: exit 0 with coverage.complete false).
echo "test_cartesian_plan.sh: planning $FIX_REL/paths3d.json"
ros2 run crackvision_motion plan_crack_path "${PLAN_ARGS[@]}" --out "$PLAN"
rc=$?
[ "$rc" -eq 0 ] || fail "plan_crack_path exit=$rc (expected 0)"
[ -f "$PLAN" ] || fail "plan_crack_path exit 0 but $PLAN not written"

# 3. Independent assertions from the plan file + this block's own /compute_fk and
#    /check_state_validity calls (the planner applied the fixture scene to move_group; this block
#    first confirms move_group's world really holds that scene before trusting validity answers).
python3 - "$REPO_ROOT" "$PLAN" "$FIX" <<'PYEOF'
import json, math, sys
import numpy as np
import rclpy
import yaml
from moveit_msgs.msg import PlanningSceneComponents, RobotState
from moveit_msgs.srv import GetPlanningScene, GetPositionFK, GetStateValidity
from sensor_msgs.msg import JointState

root, plan_path, fix = sys.argv[1:4]
JOINTS = [f"joint{i}" for i in range(1, 7)]
TOL_M, TOL_DEG = 0.001, 1.0
INTERP = (0.0, 0.25, 0.5, 0.75)    # joint-space fractions FK-checked between consecutive trace configs
GOAL_JOINT_TOL = 0.001              # plan_crack_path's joint-goal constraint tolerance (cartesian_moveit.py)
failures = []


def check(cond, msg):
    if not cond:
        failures.append(msg)
    return cond


plan = json.load(open(plan_path))
exp = json.load(open(f"{fix}/expected.json"))
paths3d = json.load(open(f"{fix}/paths3d.json"))
limits = yaml.safe_load(open(f"{root}/config/robot/b601_dm_limits.yaml"))["joints"]
max_step = plan["parameters"]["recheck"]["max_joint_step_rad"]
z_trace = exp["surface_z_m"] + exp["trace_clearance_m"]
n_out = np.array([0.0, 0.0, 1.0])

check(plan["schema"] == "crackvision.cartesian_plan/1", "schema")
check(plan["joint_names"] == JOINTS, "joint_names")
check(plan["sources"]["scene"]["path"] == f"{fix[len(root) + 1:]}/scene.yaml", f"scene source {plan['sources']['scene']}")
check(plan["sources"]["paths3d"]["execution_eligible"] is False, "sources.paths3d.execution_eligible must be false")
check(plan["start_state"]["source"] == "capture_record"
      and np.allclose(plan["start_state"]["positions_rad"], exp["start_joints"], atol=1e-9), "start_state")


def key(ref):
    return (ref["component_id"], ref["polyline_kind"], ref["branch_index"], ref["segment_index"])


# fixture trace waypoints / surface points per segment, straight from paths3d.json
fixture = {}
for comp in paths3d["components"]:
    for pl in comp["polylines"]:
        for si, seg in enumerate(pl["segments"]):
            wps = seg["waypoints"]
            fixture[(comp["component_id"], pl["kind"], pl["branch_index"], si)] = {
                "trace": np.array([w["position_m"] for w in wps if w["phase"] == "trace"]),
                "surface": np.array([w["surface_point_m"] for w in wps if w["phase"] == "trace"]),
            }

# --- segments[] statuses ----------------------------------------------------------------------
reports = {}
for s in plan["segments"]:
    reports.setdefault(key(s["segment_ref"]), []).append(s)
check(len(reports) == len(exp["segments"]), f"segment keys {sorted(reports)}")
full_keys = []
for es in exp["segments"]:
    k = key(es["segment_ref"])
    entries = reports.get(k, [])
    orig = [e for e in entries if e["segment_ref"]["sub_segment"] is None]
    if not check(len(orig) == 1, f"{k}: expected one original segments[] entry, got {len(orig)}"):
        continue
    o = orig[0]
    check(o["trace_waypoints"]["total"] == es["trace_waypoints"], f"{k}: total {o['trace_waypoints']}")
    check(abs(o["trace_length_m"]["total"] - es["trace_length_m"]) < 1e-9, f"{k}: length {o['trace_length_m']}")
    if es["expected_status"] == "full":
        full_keys.append(k)
        check(o["status"] == "full" and o["trace_waypoints"]["planned"] == es["trace_waypoints"]
              and o["chosen"] is not None and len(entries) == 1, f"{k}: expected full, got {o}")
    elif es["expected_status"] == "failed":
        check(o["status"] == "failed" and o["trace_waypoints"]["planned"] == 0 and o["chosen"] is None
              and o["candidates_tried"] > 0 and len(o["reasons"]) > 0 and len(entries) == 1,
              f"{k}: expected failed with reasons, got {o}")
    elif es["expected_status"] == "surface_scene_mismatch":
        check(o["status"] == "surface_scene_mismatch" and o["candidates_tried"] == 0 and o["chosen"] is None
              and o["trace_waypoints"]["planned"] == 0 and len(o["reasons"]) > 0 and len(entries) == 1,
              f"{k}: expected surface_scene_mismatch, got {o}")
        check(not any(l["segment_ref"] and key(l["segment_ref"]) == k for l in plan["legs"]),
              f"{k}: a surface_scene_mismatch segment has legs")
check(len(full_keys) == 2, "fixture must contain two reachable segments")

# --- coverage -----------------------------------------------------------------------------------
cov = plan["coverage"]
full_wp = sum(es["trace_waypoints"] for es in exp["segments"] if es["expected_status"] == "full")
check(cov["trace_waypoints_total"] == exp["trace_waypoints_total"], f"coverage total {cov}")
check(cov["trace_waypoints_planned"] == full_wp, f"coverage planned {cov['trace_waypoints_planned']} != {full_wp}")
check(abs(cov["length_m_total"] - exp["length_m_total"]) < 1e-9, f"coverage length {cov}")
check(abs(cov["fraction_by_length"] - exp["fraction_by_length"]) < 1e-9,
      f"fraction_by_length {cov['fraction_by_length']} != expected {exp['fraction_by_length']}")
check(cov["complete"] is False, "coverage.complete must be false")

# --- legs: order, continuity, limits, joint step -------------------------------------------------
legs = plan["legs"]
check([l["leg_index"] for l in legs] == list(range(len(legs))), "leg_index not 0..n-1")
check(len(legs) == 4 * len(full_keys) + 1, f"expected {4 * len(full_keys) + 1} legs, got {len(legs)}")
check(legs[-1]["segment_ref"] is None and legs[-1]["kind"] == "transit", "missing trailing end_state transit")
prev_end = np.array(plan["start_state"]["positions_rad"])
for l in legs:
    pos = np.array(l["positions"], dtype=float)
    check(pos.ndim == 2 and pos.shape[1] == 6 and len(pos) >= 1, f"leg {l['leg_index']} shape {pos.shape}")
    check(np.max(np.abs(pos[0] - prev_end)) <= 1e-4,
          f"leg {l['leg_index']} discontinuous: starts {pos[0].tolist()} after {prev_end.tolist()}")
    if len(pos) > 1:
        step = float(np.max(np.abs(np.diff(pos, axis=0))))
        check(step <= max_step, f"leg {l['leg_index']} joint step {step} > {max_step}")
    for j, name in enumerate(JOINTS):
        lo, hi = limits[name]["lower"], limits[name]["upper"]
        check(bool(np.all((pos[:, j] >= lo) & (pos[:, j] <= hi))), f"leg {l['leg_index']} {name} outside [{lo},{hi}]")
    prev_end = pos[-1]
end_err = float(np.max(np.abs(prev_end - np.array(plan["end_state"]["positions_rad"]))))
check(plan["end_state"]["mode"] == "start" and end_err <= GOAL_JOINT_TOL,
      f"plan does not end at end_state (max joint error {end_err} > {GOAL_JOINT_TOL})")
for k in full_keys:
    kinds = [l["kind"] for l in legs if l["segment_ref"] and key(l["segment_ref"]) == k]
    check(kinds == ["transit", "approach", "trace", "retract"], f"{k}: leg kinds {kinds}")

# --- independent ROS checks ----------------------------------------------------------------------
rclpy.init()
node = rclpy.create_node("test_cartesian_plan_check")


def call(client, req):
    fut = client.call_async(req)
    rclpy.spin_until_future_complete(node, fut, timeout_sec=30.0)
    if not fut.done() or fut.result() is None:
        raise RuntimeError(f"service call to {client.srv_name} did not complete")
    return fut.result()


fk_cli = node.create_client(GetPositionFK, "/compute_fk")
val_cli = node.create_client(GetStateValidity, "/check_state_validity")
scene_cli = node.create_client(GetPlanningScene, "/get_planning_scene")
for c in (fk_cli, val_cli, scene_cli):
    if not c.wait_for_service(timeout_sec=30.0):
        sys.exit(f"service {c.srv_name} unavailable")


def robot_state(q):
    rs = RobotState()
    rs.joint_state = JointState(name=JOINTS, position=[float(v) for v in q])
    return rs


counts = {"fk": 0}


def fk(q):
    req = GetPositionFK.Request()
    req.header.frame_id = "base_link"
    req.fk_link_names = ["tool_tip"]
    req.robot_state = robot_state(q)
    resp = call(fk_cli, req)
    counts["fk"] += 1
    if resp.error_code.val != 1 or len(resp.pose_stamped) != 1:
        raise RuntimeError(f"/compute_fk error {resp.error_code.val}")
    p, o = resp.pose_stamped[0].pose.position, resp.pose_stamped[0].pose.orientation
    x, y, z, w = o.x, o.y, o.z, o.w
    x_axis = np.array([1 - 2 * (y * y + z * z), 2 * (x * y + z * w), 2 * (x * z - y * w)])
    return np.array([p.x, p.y, p.z]), x_axis


def valid(q):
    req = GetStateValidity.Request()
    req.group_name = "arm"
    req.robot_state = robot_state(q)
    return bool(call(val_cli, req).valid)


def boresight_err_deg(x_axis):
    return math.degrees(math.acos(max(-1.0, min(1.0, float(np.dot(x_axis, -n_out))))))


def dist_to_polyline(p, poly):
    best = math.inf
    for a, b in zip(poly[:-1], poly[1:]):
        ab = b - a
        t = min(1.0, max(0.0, float(np.dot(p - a, ab) / np.dot(ab, ab))))
        best = min(best, float(np.linalg.norm(p - (a + t * ab))))
    return best


# The scene the validity oracle answers against must be the fixture scene.
sreq = GetPlanningScene.Request()
sreq.components.components = PlanningSceneComponents.WORLD_OBJECT_GEOMETRY
world = {o.id: o for o in call(scene_cli, sreq).scene.world.collision_objects}
spec = world.get("specimen")
if check(spec is not None and "table" in world, f"move_group world objects {sorted(world)}"):
    centre = np.array([spec.pose.position.x, spec.pose.position.y, spec.pose.position.z])
    if spec.primitive_poses:
        pp = spec.primitive_poses[0].position
        centre = centre + np.array([pp.x, pp.y, pp.z])
    check(np.allclose(centre, exp["specimen"]["position_m"], atol=1e-6)
          and np.allclose(list(spec.primitives[0].dimensions), exp["specimen"]["dimensions_m"], atol=1e-6),
          f"move_group specimen {centre.tolist()} {list(spec.primitives[0].dimensions)} != fixture {exp['specimen']}")

n_valid = 0
for l in legs:
    for q in l["positions"]:
        n_valid += 1
        if not valid(q):
            check(False, f"leg {l['leg_index']} ({l['kind']}) configuration invalid per /check_state_validity: {q}")
            break

worst = {"trace_pos": 0.0, "trace_ang": 0.0, "end_pos": 0.0, "end_ang": 0.0}
for k in full_keys:
    fx = fixture[k]
    seg_legs = {l["kind"]: l for l in legs if l["segment_ref"] and key(l["segment_ref"]) == k}
    if set(seg_legs) != {"transit", "approach", "trace", "retract"}:
        continue
    ends = [fx["surface"][0], fx["surface"][-1]]

    # trace: every configuration, and the joint-space interpolation between consecutive ones (what a
    # controller would execute), on the 0.01 m offset polyline with boresight along -n ...
    tq = np.array(seg_legs["trace"]["positions"], dtype=float)
    swept = []
    for i in range(len(tq)):
        for f in ((0.0,) if i == len(tq) - 1 else INTERP):
            q = tq[i] if f == 0.0 else (1.0 - f) * tq[i] + f * tq[i + 1]
            p, xa = fk(q)
            swept.append(p)
            d, a = dist_to_polyline(p, fx["trace"]), boresight_err_deg(xa)
            dz = abs(p[2] - z_trace)
            worst["trace_pos"], worst["trace_ang"] = max(worst["trace_pos"], d, dz), max(worst["trace_ang"], a)
            check(d <= TOL_M and dz <= TOL_M and a <= TOL_DEG,
                  f"{k}: trace config {i}+{f} off-path: dist {d:.5f} m, dz {dz:.5f} m, boresight {a:.3f} deg")
    # ... and every fixture trace waypoint (surface_point + 0.01 n) lies on that swept tool path
    swept = np.array(swept)
    miss = [j for j, w in enumerate(fx["surface"] + exp["trace_clearance_m"] * n_out)
            if (dist_to_polyline(w, swept) if len(swept) > 1 else float(np.linalg.norm(w - swept[0]))) > TOL_M]
    check(not miss, f"{k}: trace waypoints not covered by the swept tool path: {miss}")

    # approach: starts 0.04 m above one end, ends at that end's trace pose; retract mirrors it
    def at(q, surface_pt, clearance, probe=False):
        p, xa = fk(q)
        e = float(np.linalg.norm(p - (surface_pt + clearance * n_out)))
        a = boresight_err_deg(xa)
        if not probe:   # finding which end the approach starts at is not itself an assertion
            worst["end_pos"], worst["end_ang"] = max(worst["end_pos"], e), max(worst["end_ang"], a)
        return e <= TOL_M and a <= TOL_DEG

    ap, rt = seg_legs["approach"]["positions"], seg_legs["retract"]["positions"]
    start_idx = [i for i in (0, 1) if at(ap[0], ends[i], exp["approach_retract_offset_m"], probe=True)]
    if check(len(start_idx) == 1, f"{k}: approach does not start 0.04 m above a segment end"):
        check(at(ap[0], ends[start_idx[0]], exp["approach_retract_offset_m"]), f"{k}: approach start")
        s_end, e_end = ends[start_idx[0]], ends[1 - start_idx[0]]
        check(at(ap[-1], s_end, exp["trace_clearance_m"]), f"{k}: approach does not end at the first trace pose")
        check(at(rt[0], e_end, exp["trace_clearance_m"]), f"{k}: retract does not start at the last trace pose")
        check(at(rt[-1], e_end, exp["approach_retract_offset_m"]), f"{k}: retract does not end 0.04 m above the far end")
    check(at(seg_legs["transit"]["positions"][-1], s_end if len(start_idx) == 1 else ends[0],
             exp["approach_retract_offset_m"]), f"{k}: transit does not end at the approach pose")

node.destroy_node()
rclpy.shutdown()

print(f"test_cartesian_plan.sh: {len(plan['segments'])} segment reports, {len(legs)} legs, "
      f"{n_valid} configs validity-checked, {counts['fk']} /compute_fk calls; worst trace offset {1000 * worst['trace_pos']:.3f} mm / "
      f"{worst['trace_ang']:.3f} deg, worst approach/retract endpoint {1000 * worst['end_pos']:.3f} mm / "
      f"{worst['end_ang']:.3f} deg; coverage {cov['trace_waypoints_planned']}/{cov['trace_waypoints_total']} "
      f"waypoints, fraction_by_length {cov['fraction_by_length']:.6f} (expected {exp['fraction_by_length']:.6f})")
for s in plan["segments"]:
    print(f"  {key(s['segment_ref'])}: {s['status']} {s['trace_waypoints']} reasons={s['reasons'][:2]}")
if failures:
    for f in failures:
        print(f"ASSERTION FAILED: {f}", file=sys.stderr)
    sys.exit(1)
PYEOF
[ $? -eq 0 ] || fail "plan assertions failed"

# 4. Same input with --require-full-coverage: refusal (exit 3), no plan file written.
echo "test_cartesian_plan.sh: re-planning with --require-full-coverage (expect exit 3)"
ros2 run crackvision_motion plan_crack_path "${PLAN_ARGS[@]}" --out "$PLAN_RFC" --require-full-coverage
rc=$?
[ "$rc" -eq 3 ] || fail "--require-full-coverage exit=$rc (expected 3)"
[ ! -e "$PLAN_RFC" ] || fail "--require-full-coverage refusal still wrote $PLAN_RFC"

# 5. Teardown (the EXIT trap also covers every early exit above).
stop_mock_stack
echo "test_cartesian_plan.sh: OK"
exit 0
